#include "window.h"
#include <QtNetwork>
#include "version.h"
static bool repositoryValid(QString repo){return QRegularExpression("^[A-Za-z0-9][A-Za-z0-9-]{0,38}/[A-Za-z0-9_.-]+$").match(repo).hasMatch()&&!repo.endsWith("/.")&&!repo.endsWith("/..");}
bool parseReleaseUpdate(const QJsonObject& release,QString repo,QString current,ReleaseUpdate& out,QString& error){
    out={};if(!repositoryValid(repo)||release["draft"].toBool()||release["prerelease"].toBool()){error=ui("发布版本无效");return false;}QString tag=release["tag_name"].toString();if(!QRegularExpression("^v?[0-9]+\\.[0-9]+\\.[0-9]+$").match(tag).hasMatch()){error=ui("发布版本号无效");return false;}
    out.version=tag.startsWith('v')?tag.mid(1):tag;auto latest=QVersionNumber::fromString(out.version),installed=QVersionNumber::fromString(current);if(latest.isNull()||installed.isNull()){error=ui("发布版本号无效");return false;}out.newer=QVersionNumber::compare(latest,installed)>0;
    QString releasePrefix="https://github.com/"+repo+"/releases/";auto page=release["html_url"].toString();if(!page.startsWith(releasePrefix,Qt::CaseInsensitive)){error=ui("发布地址无效");return false;}out.download=QUrl(page);QString name="PSDNaming-v"+out.version+"-win-x64.zip";
    for(auto item:release["assets"].toArray()){auto asset=item.toObject();QString url=asset["browser_download_url"].toString();if((asset["name"].toString()==name||asset["name"].toString()=="PSD-Renamer-v"+out.version+"-win-x64.zip")&&url.startsWith(releasePrefix+"download/",Qt::CaseInsensitive)&&asset["state"].toString()=="uploaded"){out.download=QUrl(url);break;}}return true;
}
void Window::checkUpdates(){
    QDialog dialog(this);dialog.setWindowTitle(ui("检查更新"));dialog.setFixedWidth(420);auto layout=new QVBoxLayout(&dialog);layout->setContentsMargins(24,24,24,20);layout->setSpacing(16);layout->addWidget(new QLabel(ui("当前版本：%1").arg(PSD_APP_VERSION),&dialog));auto status=new QLabel(ui("正在检查更新…"),&dialog);status->setObjectName("updateStatus");status->setWordWrap(true);layout->addWidget(status);auto download=new QPushButton(ui("下载新版"),&dialog);download->setVisible(false);layout->addWidget(download);auto buttons=new QDialogButtonBox(QDialogButtonBox::Close,&dialog);buttons->button(QDialogButtonBox::Close)->setText(ui("关闭"));layout->addWidget(buttons);connect(buttons,&QDialogButtonBox::rejected,&dialog,&QDialog::reject);
    QFile source(QCoreApplication::applicationDirPath()+"/update-source.json");QString repo;if(source.open(QIODevice::ReadOnly))repo=QJsonDocument::fromJson(source.readAll()).object()["repository"].toString().trimmed();QNetworkAccessManager network(&dialog);QNetworkReply* reply=nullptr;
    if(!repositoryValid(repo))status->setText(ui("尚未配置更新仓库"));else {QNetworkRequest request(QUrl("https://api.github.com/repos/"+repo+"/releases/latest"));request.setRawHeader("Accept","application/vnd.github+json");request.setRawHeader("User-Agent",QByteArray("PSDNaming/")+PSD_APP_VERSION);request.setRawHeader("X-GitHub-Api-Version","2026-03-10");request.setTransferTimeout(15000);request.setAttribute(QNetworkRequest::RedirectPolicyAttribute,QNetworkRequest::NoLessSafeRedirectPolicy);reply=network.get(request);
        connect(reply,&QNetworkReply::downloadProgress,&dialog,[reply](qint64 received,qint64){if(received>1024*1024)reply->abort();});connect(reply,&QNetworkReply::finished,&dialog,[&,repo,reply]{int http=reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();if(reply->error()!=QNetworkReply::NoError){status->setText(http==404?ui("仓库不可用或尚无正式版本"):http==403||http==429?ui("检查更新受限，请稍后重试"):ui("无法连接更新服务"));reply->deleteLater();return;}QJsonParseError parse;auto json=QJsonDocument::fromJson(reply->readAll(),&parse);ReleaseUpdate update;QString error;if(parse.error!=QJsonParseError::NoError||!json.isObject()||!parseReleaseUpdate(json.object(),repo,PSD_APP_VERSION,update,error)){status->setText(error.isEmpty()?ui("更新数据无效"):error);}else if(!update.newer)status->setText(ui("已是最新版本"));else{status->setText(ui("发现新版：%1").arg(update.version));download->setText(update.download.path().contains("/download/")?ui("下载新版"):ui("打开发布页"));download->setVisible(true);connect(download,&QPushButton::clicked,&dialog,[url=update.download]{QDesktopServices::openUrl(url);});}reply->deleteLater();});}
    dialog.exec();
}
